package com.ml.tblandroidtxt;
import org.json.JSONArray;import org.json.JSONObject;
/** Contract for one checkpointable L2 edit scene; chapter-level gates are aggregated later. */
public final class EditorialL2SceneContract {
 public static String schema(){return "{\"sceneId\":\"string\",\"rawStart\":\"anchor\",\"rawEnd\":\"anchor\",\"output\":\"full scene VI\",\"outputComplete\":true,\"changes\":[{\"id\":\"string\",\"before\":\"string\",\"after\":\"string\",\"reason\":\"string\",\"scope\":\"string\",\"status\":\"CLOSED\"}],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";}
 public static String validate(String text){try{JSONObject r=new JSONObject(text);if(blank(r.optString("sceneId"))||blank(r.optString("rawStart"))||blank(r.optString("rawEnd"))||blank(r.optString("output"))||!r.optBoolean("outputComplete",false))return "L2 scene output is incomplete";JSONArray changes=r.optJSONArray("changes");if(changes==null)return "Missing L2 scene changes";for(int i=0;i<changes.length();i++){JSONObject x=changes.optJSONObject(i);if(x==null||blank(x.optString("id"))||blank(x.optString("before"))||blank(x.optString("after"))||blank(x.optString("reason"))||blank(x.optString("scope"))||!"CLOSED".equals(x.optString("status")))return "Incomplete L2 scene change";}JSONObject g=r.optJSONObject("gates");if(g==null)return "Missing L2 scene gates";for(String k:new String[]{"coverage","fidelity","referenceVoice","continuityStructure","change"})if(!"CLOSED".equals(g.optString(k)))return "L2 scene gate is open: "+k;return null;}catch(Exception e){return "Invalid L2 scene JSON";}}
 private static boolean blank(String x){return x==null||x.trim().isEmpty();}private EditorialL2SceneContract(){}
}
